            if not (MIN_DECISION_LEN <= len(s) <= MAX_DECISION_LEN):
                continue
            low = s.lower()
            for kind, markers in DECISION_MARKERS:
                if any(m in low for m in markers):
                    key = s[:120].lower()
                    if key not in seen:
                        seen.add(key)
                        found.append(Decision(kind=kind, text=s, speaker=speaker))
                    break
    return found

