def verify(self, test_command: str, timeout: int = 600) -> GraphResult:
    """Run a test command and return an adjudicated verdict.

    Deliberately uses ``entire graph verify`` rather than running the tests
    ourselves: it reports *which tests changed state* - newly passing,
    newly failing, or already failing before the edit - instead of dumping
    runner output. That distinction is the whole point when the question is
    "does the change I am assessing break anything", because a test that
    was already red is not evidence against this change.
    """
    previous, self.timeout = self.timeout, timeout
    try:
        return self._run(
            ["graph", "verify", "--repo", self.repo, "--test", test_command]
        )
    finally:
        self.timeout = previous

